import json, sys, html as _h

BOOK = {'title': 'Captain Captain Will Hawkins', 'author': 'Signature original', 'genre': 'Port Towns', 'chapters': [{'n': 1, 'title': 'The Chart', 'text': "The crew signed on with the articles read aloud: shares, rules, no desertion. Captain Will Hawkins added one article of their own: 'loyalty above gold.' The crew cheered. Pirates are sentimentalists at heart.\n\nThat night Captain Will Hawkins stood at the wheel with a captain's log's copy memorized and the original safe. Stars overhead, Captain Blackheart astern, Tortuga behind. loyalty above gold — the sea was about to test it.\n\nCaptain Blackheart's sail was spotted on the third day — a black speck that didn't go away. 'They want a captain's log,' the cook said. Captain Will Hawkins nodded. 'Then they'll have to take it.' The crew cleared for action, grinning. They'd signed for this."}, {'n': 2, 'title': 'The Chase', 'text': "Captain Blackheart closed in at the strait — the only passage, and Captain Blackheart across it like a door. The parley was short: 'a captain's log for your lives.' Captain Will Hawkins's answer was shorter, and involved cannon.\n\nThey took Captain Blackheart's survivors aboard in irons — pirates have rules about the sea, even for enemies. 'The island eats ships,' Captain Will Hawkins told the prisoners. 'Let's see if it eats villains too.'\n\nThe chase ran eleven days through Tortuga's waters: storms, calms, a reef that took Captain Blackheart's foretopmast and gave Captain Will Hawkins half a day. the cook's navigation was witchcraft; the crew swore the compass loved them."}, {'n': 3, 'title': "Dead Man's Cay", 'text': "The gold was there too — don't worry, there was gold — but Captain Will Hawkins understood: a captain's log was bigger than one chest. It was a lifetime of plunder, mapped. Enough to buy a fleet. Or a pardon. Or a future.\n\nThe point arrived with the cave's guardians — the island's eaters, whatever they were, stone and shadow. In the chaos Captain Will Hawkins seized a captain's log, the cook seized the gold, and they ran for the ship with the dark at their heels.\n\nInland: jungle, then ruins, then the cave. a captain's log's X marked a chamber sealed a century. Inside: not gold — at first. A tomb. A logbook. The real a captain's log: the captain's confession, naming every cache along Tortuga."}, {'n': 4, 'title': 'The Reckoning', 'text': "They sailed for Tortuga with the gold and a captain's log and the logbook's secrets. The crew's shares would make them rich. Captain Will Hawkins's share would make them legend. the cook was already spending theirs on a tavern.\n\nthe cook fought like three people. The crew fought like the sea itself. Captain Will Hawkins faced Captain Blackheart with cutlasses and old scores, and the duel was the kind they sing about: give, take, blood in the sand, neither yielding.\n\nIt ended as these things do: Captain Blackheart overreached, Captain Will Hawkins didn't, and the sea took Captain Blackheart with the tide. Captain Will Hawkins stood in the surf, breathing hard, a captain's log safe. 'Bury them decent,' Captain Will Hawkins ordered. Pirates have rules."}, {'n': 5, 'title': 'Port and Pardon', 'text': "the cook's tavern opened to packed crowds: 'The a captain's log.' The sign showed Captain Will Hawkins with a cutlass and a grin. Captain Will Hawkins pretended to mind. Nobody believed it.\n\nSome of the crew shipped out again, chasing the logbook's caches. Captain Will Hawkins stayed — for a season. The sea calls, and Captain Will Hawkins always answers. But home, Captain Will Hawkins was learning, is also an answer.\n\nCaptain Will Hawkins took the logbook to the governor — not Captain Blackheart's governor, the new one — and traded certain pages for a pardon, signed and sealed. The crew cheered. Respectability, it turns out, is its own adventure."}, {'n': 6, 'title': 'The Tide Returns', 'text': "Captain Blackheart's successor was out there somewhere — there's always a successor. Captain Will Hawkins wasn't worried. The sea decides, and the sea loves the bold.\n\nA year later, a new a captain's log surfaced — they always do — and Captain Will Hawkins was packed before the ink dried. the cook closed the tavern for 'renovations' and came along, because that's what friends do.\n\nThe new crew was young and wide-eyed. Captain Will Hawkins read them the articles, including the added one. They cheered, the way crews do. Pirates are sentimentalists. It's why they survive."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

